//! Detector tests: NeuroKit2 parity of the Elgendi detector (synthetic `nk.ecg_simulate` fixtures in
//! `tests/data/neurokit_elgendi.json`, generated by `tools/detect_reference.py`).
//!
//! The tests FAIL if the reference file is missing; set `FAST_HRV_SKIP_PARITY=1` to skip them.

use fast_hrv::detect::{ElgendiConfig, elgendi_filter, elgendi_peaks};
use serde_json::Value;

const SKIP_ENV: &str = "FAST_HRV_SKIP_PARITY";

fn load(name: &str) -> Option<Value> {
    let path = format!("{}/tests/data/{name}", env!("CARGO_MANIFEST_DIR"));
    match std::fs::read_to_string(&path) {
        Ok(text) => Some(serde_json::from_str(&text).unwrap_or_else(|e| panic!("{path}: {e}"))),
        Err(e) => {
            if std::env::var(SKIP_ENV).is_ok_and(|v| v == "1") {
                eprintln!("{path} missing ({e}); skipped because {SKIP_ENV}=1");
                None
            } else {
                panic!(
                    "NeuroKit2 reference {path} missing ({e}). Generate it with \
                     `python tools/detect_reference.py` or set {SKIP_ENV}=1 to skip."
                )
            }
        }
    }
}

fn b64_decode(s: &str) -> Vec<u8> {
    let val = |c: u8| -> u32 {
        match c {
            b'A'..=b'Z' => (c - b'A') as u32,
            b'a'..=b'z' => (c - b'a' + 26) as u32,
            b'0'..=b'9' => (c - b'0' + 52) as u32,
            b'+' => 62,
            b'/' => 63,
            _ => panic!("bad base64"),
        }
    };
    let bytes: Vec<u8> = s.bytes().filter(|&c| c != b'=').collect();
    let mut out = Vec::with_capacity(bytes.len() * 3 / 4);
    for chunk in bytes.chunks(4) {
        let mut acc = 0u32;
        for (i, &c) in chunk.iter().enumerate() {
            acc |= val(c) << (18 - 6 * i);
        }
        for i in 0..chunk.len() * 6 / 8 {
            out.push((acc >> (16 - 8 * i)) as u8);
        }
    }
    out
}

fn decode_i16(s: &str) -> Vec<f64> {
    b64_decode(s)
        .chunks(2)
        .map(|c| i16::from_le_bytes([c[0], c[1]]) as f64)
        .collect()
}

fn decode_f64(s: &str) -> Vec<f64> {
    b64_decode(s)
        .chunks(8)
        .map(|c| f64::from_le_bytes(c.try_into().unwrap()))
        .collect()
}

fn usizes(v: &Value) -> Vec<usize> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_u64().unwrap() as usize)
        .collect()
}

struct Case {
    name: String,
    fs: f64,
    raw: Vec<f64>,
    filtered_step: usize,
    filtered: Vec<f64>,
    nk2010: Vec<usize>,
    nk2013: Vec<usize>,
}

fn cases() -> Option<(String, Vec<Case>)> {
    let r = load("neurokit_elgendi.json")?;
    let cases = r["cases"]
        .as_array()
        .unwrap()
        .iter()
        .map(|c| Case {
            name: c["name"].as_str().unwrap().to_string(),
            fs: c["sampling_rate"].as_f64().unwrap(),
            raw: decode_i16(c["raw_i16_b64"].as_str().unwrap()),
            filtered_step: c["filtered_step"].as_u64().unwrap() as usize,
            filtered: decode_f64(c["filtered_f64_b64"].as_str().unwrap()),
            nk2010: usizes(&c["peaks_elgendi2010"]),
            nk2013: usizes(&c["peaks_elgendi2013"]),
        })
        .collect();
    Some((r["versions"].to_string(), cases))
}

#[test]
fn elgendi_filter_matches_neurokit() {
    let Some((versions, cases)) = cases() else {
        return;
    };
    eprintln!("NeuroKit2 {versions}");
    for c in &cases {
        let y = elgendi_filter(&c.raw, c.fs, &ElgendiConfig::default()).unwrap();
        let scale = c.filtered.iter().fold(0.0f64, |m, v| m.max(v.abs()));
        let mut worst = 0.0f64;
        for (k, &want) in c.filtered.iter().enumerate() {
            worst = worst.max((y[k * c.filtered_step] - want).abs() / scale);
        }
        eprintln!(
            "8–20 Hz filter {}: max |diff| / max|y| = {worst:.2e}",
            c.name
        );
        assert!(worst < 1e-9, "{}: filter differs ({worst:e})", c.name);
    }
}

#[test]
fn elgendi_peaks_match_neurokit_before_refinement() {
    let Some((versions, cases)) = cases() else {
        return;
    };
    eprintln!("NeuroKit2 {versions}");
    for c in &cases {
        for (label, cfg, want) in [
            ("elgendi2010", ElgendiConfig::neurokit2010(), &c.nk2010),
            ("elgendi2013", ElgendiConfig::neurokit2013(), &c.nk2013),
            // Default = elgendi2013 + 0.3 s refractory; on these signals the refractory never fires.
            ("default", ElgendiConfig::default(), &c.nk2013),
        ] {
            let got = elgendi_peaks(&c.raw, c.fs, &cfg).unwrap();
            let same = want.iter().filter(|p| got.contains(p)).count();
            eprintln!(
                "{:<18} {label:<11}: NK {:>3}  fast-hrv {:>3}  identical {same}",
                c.name,
                want.len(),
                got.len()
            );
            assert_eq!(&got, want, "{} {label}: peaks differ", c.name);
        }
    }
}
